values
('vocab_threaten','threaten','verb','to put someone or something at risk of harm or loss','[{"senseId":"threaten_1","meaning":"to put someone or something at risk of harm or loss","acceptedParaphrases":["put at risk","endanger"],"masteryContexts":[{"contextId":"u1_11_threaten_meaning","text":"A serious knee injury could threaten her place in the national squad.","meaning":"put something valuable at serious risk"},{"contextId":"u1_11_threaten_paraphrase","text":"Poor funding may threaten the future of the community football club.","meaning":"make harm or loss more likely"}],"contextDependentParaphrases":[],"misleadingDistractors":["protect","support","improve"],"grammarForms":{"base":"threaten","thirdPerson":"threatens","past":"threatened","pastParticiple":"threatened","ing":"threatening"},"grammarPatterns":["threaten + noun","threaten + to-infinitive"]}]'::jsonb,'["threat","threatening"]'::jsonb,'[]'::jsonb,'live'),
('vocab_resent','resent','verb','to feel angry or upset about something you think is unfair','[{"senseId":"resent_1","meaning":"to feel angry or upset about something you think is unfair","acceptedParaphrases":["feel bitter about","feel angry about"],"masteryContexts":[{"contextId":"u1_12_resent_meaning","text":"He began to resent being left out of the team, even though he had trained hard all season.","meaning":"feel bitter about unfair treatment"},{"contextId":"u1_12_resent_paraphrase","text":"Many workers resent being told to stay late without extra pay.","meaning":"remain angry about perceived unfairness"}],"contextDependentParaphrases":[],"misleadingDistractors":["celebrate","recommend","permit"],"grammarForms":{"base":"resent","thirdPerson":"resents","past":"resented","pastParticiple":"resented","ing":"resenting"},"grammarPatterns":["resent + noun","resent + -ing","resent + object + -ing"]}]'::jsonb,'["resentment","resentful"]'::jsonb,'[]'::jsonb,'live'),
('vocab_regret','regret','verb','to feel sorry about something that happened or something you did','[{"senseId":"regret_1","meaning":"to feel sorry about something that happened or something you did","acceptedParaphrases":["feel sorry about","wish had been different"],"masteryContexts":[{"contextId":"u1_13_regret_meaning","text":"He told me that he will always regret his own decision to leave school so early and often wishes he had stayed.","meaning":"feel sorry about a past choice"},{"contextId":"u1_13_regret_paraphrase","text":"We regret to tell you that your application has not been successful this year.","meaning":"wish a past outcome were different"}],"contextDependentParaphrases":[],"misleadingDistractors":["celebrate","demand","deny"],"grammarForms":{"base":"regret","thirdPerson":"regrets","past":"regretted","pastParticiple":"regretted","ing":"regretting"},"grammarPatterns":["regret + -ing","regret + that-clause"]}]'::jsonb,'["regrettable","regretful"]'::jsonb,'[]'::jsonb,'live'),
('vocab_unfamiliar','unfamiliar','adjective','not known or recognised because you have not experienced it before','[{"senseId":"unfamiliar_1","meaning":"not known or recognised because you have not experienced it before","acceptedParaphrases":["not known","new to you"],"masteryContexts":[{"contextId":"u1_14_unfamiliar_meaning","text":"Many of the rules in baseball seemed unfamiliar to the exchange students, because none of them had ever watched a game.","meaning":"not recognised from previous experience"},{"contextId":"u1_14_unfamiliar_paraphrase","text":"Moving to another country means getting used to unfamiliar food, customs and routines.","meaning":"new or unknown to someone"}],"contextDependentParaphrases":[],"misleadingDistractors":["famous","comfortable","ordinary"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_racquet','racquet','noun','a sports implement with a handle and strung frame used to hit a ball or shuttlecock','[{"senseId":"racquet_1","meaning":"a sports implement with a handle and strung frame used to hit a ball or shuttlecock","acceptedParaphrases":["sports bat with strings","strung sports implement"],"masteryContexts":[{"contextId":"u1_15_racquet_meaning","text":"She replaced the broken strings on her tennis racquet before the final.","meaning":"strung hand-held equipment for hitting"},{"contextId":"u1_15_racquet_paraphrase","text":"In badminton, players hit the shuttlecock over the net with a light racquet.","meaning":"handled sports frame with strings"}],"contextDependentParaphrases":[],"misleadingDistractors":["helmet","whistle","net"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_opponent','opponent','noun','a person or team you compete against','[{"senseId":"opponent_1","meaning":"a person or team you compete against","acceptedParaphrases":["competitor you face","rival"],"masteryContexts":[{"contextId":"u1_16_opponent_meaning","text":"The tennis player shook hands with her opponent, who had just beaten her in three sets.","meaning":"person or team competing against you"},{"contextId":"u1_16_opponent_paraphrase","text":"Before the game, the captain studied video of the other team’s goalkeeper to find the opponent’s weaknesses.","meaning":"the other side in a contest"}],"contextDependentParaphrases":[],"misleadingDistractors":["coach","spectator","teammate"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_intense','intense','adjective','very strong, serious, or demanding','[{"senseId":"intense_1","meaning":"very strong, serious, or demanding","acceptedParaphrases":["very demanding","extremely strong"],"masteryContexts":[{"contextId":"u1_17_intense_meaning","text":"Players faced intense pressure in the final minutes, with the score level and the whole crowd roaring.","meaning":"extreme in strength or effort"},{"contextId":"u1_17_intense_paraphrase","text":"The sun was so intense that the runners had to stop for water every few minutes.","meaning":"requiring very great energy or focus"}],"contextDependentParaphrases":[],"misleadingDistractors":["gentle","casual","brief"]}]'::jsonb,'[]'::jsonb,'["intense competition","intense training"]'::jsonb,'live'),
('vocab_tournament','tournament','noun','a competition involving several players or teams over a series of matches','[{"senseId":"tournament_1","meaning":"a competition involving several players or teams over a series of matches","acceptedParaphrases":["competition","series of matches"],"masteryContexts":[{"contextId":"u1_18_tournament_meaning","text":"Sixteen schools entered the knockout tournament, and only the winners of each match went through to the next round.","meaning":"organised competition with several matches"},{"contextId":"u1_18_tournament_paraphrase","text":"He scored the winning goal in the semi-final of the tournament, which his team went on to win.","meaning":"multi-match event that determines a winner"}],"contextDependentParaphrases":[],"misleadingDistractors":["practice","lesson","journey"]}]'::jsonb,'[]'::jsonb,'["enter a tournament","tournament final"]'::jsonb,'live'),
('vocab_determined','determined','adjective','firmly decided to achieve something and unwilling to give up','[{"senseId":"determined_1","meaning":"firmly decided to achieve something and unwilling to give up","acceptedParaphrases":["strongly motivated","resolved"],"masteryContexts":[{"contextId":"u1_19_determined_meaning","text":"Even after three defeats, she was determined to qualify for the national team and refused to give up.","meaning":"firmly committed to achieving an aim"},{"contextId":"u1_19_determined_paraphrase","text":"The team was determined to win the match despite being two goals behind at half-time.","meaning":"unwilling to give up on a goal"}],"contextDependentParaphrases":[],"misleadingDistractors":["uncertain","careless","relaxed"]}]'::jsonb,'["determine","determination"]'::jsonb,'["determined to succeed"]'::jsonb,'live'),
('vocab_discipline','discipline','noun','the self-control needed to follow rules or work consistently toward a goal','[{"senseId":"discipline_1","meaning":"the self-control needed to follow rules or work consistently toward a goal","acceptedParaphrases":["self-control","consistent control"],"masteryContexts":[{"contextId":"u1_20_discipline_meaning","text":"Training at five every morning in winter takes real discipline, because nobody forces you to keep to the routine.","meaning":"self-control that supports consistent effort"},{"contextId":"u1_20_discipline_paraphrase","text":"Success in a sport depends on talent, but it also depends on the discipline to follow a strict timetable even when you feel tired.","meaning":"controlled behaviour for following a plan"}],"contextDependentParaphrases":[],"misleadingDistractors":["luck","talent","entertainment"],"teacherNote":"Use the self-control/training sense here, not punishment or a school subject."}]'::jsonb,'["disciplined","undisciplined"]'::jsonb,'["self-discipline","training discipline"]'::jsonb,'live')
